package configbug
import "time"
type Config struct{Timeout time.Duration}
type Client struct{Timeout time.Duration}
func NewClient(cfg Config)*Client{return newHTTPClient()}
func newHTTPClient()*Client{return &Client{Timeout:30*time.Second}}

package configbug
import("testing";"time")
func TestTimeoutPropagates(t *testing.T){c:=NewClient(Config{Timeout:2*time.Second});if c.Timeout!=2*time.Second{t.Fatalf("got %v",c.Timeout)}}

package configbug
import "time"
type Config struct{Timeout time.Duration}
type Client struct{Timeout time.Duration}
func NewClient(cfg Config)*Client{c:=newHTTPClient();if cfg.Timeout>0{c.Timeout=cfg.Timeout};return c}
func newHTTPClient()*Client{return &Client{Timeout:30*time.Second}}

